import React, { useState, useEffect } from 'react';
import Sidebar from '../components/Sidebar';
import Header from '../components/Header';
import api from '../services/api';
import { Users, GraduationCap, Activity, Search, TrendingUp, Calendar, Bell } from 'lucide-react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell
} from 'recharts';

const Dashboard = () => {
  const [statistics, setStatistics] = useState({ students: 0, faculty: 0, active: 0, total: 0 });
  const [popularSearches, setPopularSearches] = useState([]);
  const [recentNotifications, setRecentNotifications] = useState([]);
  const [departmentData, setDepartmentData] = useState([]);
  const [searchTrends, setSearchTrends] = useState([]);
  const [loading, setLoading] = useState(true);

  // Department colors for pie chart
  const COLORS = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899', '#06B6D4', '#84CC16'];

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      
      // Fetch statistics
      const statsRes = await api.get('/statistics');
      setStatistics(statsRes.data);
      
      // Fetch popular searches
      const popularRes = await api.get('/search/popular?limit=5');
      setPopularSearches(popularRes.data.popular_searches || []);
      
      // Fetch notifications
      const notificationsRes = await api.get('/notifications?limit=5');
      setRecentNotifications(notificationsRes.data || []);
      
      // Fetch all students to calculate department distribution
      const studentsRes = await api.get('/people?role=student');
      const students = studentsRes.data || [];
      
      // Calculate department distribution
      const departmentCount = {};
      students.forEach(student => {
        const dept = student.department;
        if (dept) {
          departmentCount[dept] = (departmentCount[dept] || 0) + 1;
        }
      });
      
      // Convert to array format for pie chart
      const deptData = Object.entries(departmentCount).map(([name, value]) => ({
        name,
        value
      }));
      
      setDepartmentData(deptData);
      
      // Generate search trends (simulated based on popular searches)
      const trends = [
        { month: 'Jan', searches: 400 },
        { month: 'Feb', searches: 600 },
        { month: 'Mar', searches: 800 },
        { month: 'Apr', searches: 750 },
        { month: 'May', searches: 900 },
        { month: 'Jun', searches: 1100 }
      ];
      setSearchTrends(trends);
      
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const statsCards = [
    {
      title: 'Total Students',
      value: statistics.students,
      icon: Users,
      color: 'bg-blue-500',
      trend: '+12%'
    },
    {
      title: 'Total Faculty',
      value: statistics.faculty,
      icon: GraduationCap,
      color: 'bg-green-500',
      trend: '+5%'
    },
    {
      title: 'Active Records',
      value: statistics.active,
      icon: Activity,
      color: 'bg-purple-500',
      trend: '+8%'
    },
    {
      title: 'Total Records',
      value: statistics.total,
      icon: Search,
      color: 'bg-orange-500',
      trend: '+10%'
    }
  ];

  if (loading) {
    return (
      <div className="flex">
        <Sidebar />
        <div className="ml-64 flex-1">
          <Header />
          <div className="p-8 flex items-center justify-center h-96">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
              <p className="mt-4 text-gray-600">Loading dashboard...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex">
      <Sidebar />
      <div className="ml-64 flex-1">
        <Header />
        
        <div className="p-8 mt-16">
          {/* Welcome Section */}
          <div className="mb-8">
            <h1 className="text-2xl font-bold text-gray-800">Dashboard Overview</h1>
            <p className="text-gray-600 mt-1">Welcome to the Intelligent School Directory System</p>
          </div>
          
          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            {statsCards.map((stat, index) => {
              const Icon = stat.icon;
              return (
                <div key={index} className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow">
                  <div className="flex items-center justify-between mb-4">
                    <div className={`${stat.color} p-3 rounded-lg`}>
                      <Icon className="text-white" size={24} />
                    </div>
                    <span className="text-green-600 text-sm font-semibold">{stat.trend}</span>
                  </div>
                  <h3 className="text-gray-500 text-sm mb-1">{stat.title}</h3>
                  <p className="text-3xl font-bold text-gray-800">{stat.value.toLocaleString()}</p>
                </div>
              );
            })}
          </div>
          
          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
            {/* Search Trends Chart */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-gray-800">Search Trends</h3>
                <TrendingUp size={20} className="text-gray-400" />
              </div>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={searchTrends}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="month" />
                  <YAxis />
                  <Tooltip />
                  <Legend />
                  <Line type="monotone" dataKey="searches" stroke="#3B82F6" strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
            </div>
            
            {/* Department Distribution Chart - Now syncs with actual student data */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-gray-800">Department Distribution</h3>
                <span className="text-sm text-gray-500">Based on {statistics.students} students</span>
              </div>
              {departmentData.length === 0 ? (
                <div className="flex items-center justify-center h-[300px] text-gray-500">
                  <div className="text-center">
                    <p>No student data available</p>
                    <p className="text-sm mt-2">Add students to see department distribution</p>
                  </div>
                </div>
              ) : (
                <ResponsiveContainer width="100%" height={300}>
                  <PieChart>
                    <Pie
                      data={departmentData}
                      cx="50%"
                      cy="50%"
                      labelLine={false}
                      label={({ name, percent }) => `${name} (${(percent * 100).toFixed(0)}%)`}
                      outerRadius={80}
                      fill="#8884d8"
                      dataKey="value"
                    >
                      {departmentData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => [`${value} students`, 'Count']} />
                  </PieChart>
                </ResponsiveContainer>
              )}
            </div>
          </div>
          
          {/* Popular Searches and Notifications */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Popular Searches */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-gray-800">Popular Searches</h3>
                <TrendingUp size={20} className="text-gray-400" />
              </div>
              <div className="space-y-3">
                {popularSearches.length === 0 ? (
                  <div className="text-center py-8 text-gray-500">
                    <p>No search data available yet</p>
                    <p className="text-sm mt-2">Start using the search feature to see trends</p>
                  </div>
                ) : (
                  popularSearches.map((search, index) => (
                    <div key={index} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                      <div className="flex items-center gap-3">
                        <span className={`font-bold ${
                          index === 0 ? 'text-yellow-500' : 
                          index === 1 ? 'text-gray-400' : 
                          index === 2 ? 'text-orange-400' : 'text-gray-500'
                        }`}>#{index + 1}</span>
                        <span className="text-gray-700 font-medium">{search.query}</span>
                      </div>
                      <span className="text-sm text-gray-500">{search.count} searches</span>
                    </div>
                  ))
                )}
              </div>
            </div>
            
            {/* Recent Notifications */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-gray-800">Recent Notifications</h3>
                <Bell size={20} className="text-gray-400" />
              </div>
              <div className="space-y-3">
                {recentNotifications.length === 0 ? (
                  <div className="text-center py-8 text-gray-500">
                    <p>No notifications</p>
                    <p className="text-sm mt-2">System is running smoothly</p>
                  </div>
                ) : (
                  recentNotifications.map((notification, index) => (
                    <div key={notification.id || index} className="flex items-start gap-3 p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                      <Bell size={16} className="text-blue-600 mt-0.5 flex-shrink-0" />
                      <div className="flex-1">
                        <p className="text-sm text-gray-700">{notification.message}</p>
                        <p className="text-xs text-gray-400 mt-1">
                          {new Date(notification.created_at).toLocaleDateString()}
                        </p>
                      </div>
                      {!notification.is_read && (
                        <span className="w-2 h-2 bg-blue-600 rounded-full flex-shrink-0 mt-1"></span>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
          
          {/* Additional Info Card */}
          <div className="mt-8 bg-gradient-to-r from-blue-50 to-indigo-50 rounded-xl p-6 border border-blue-100">
            <h3 className="text-lg font-semibold text-gray-800 mb-2">System Intelligence Features</h3>
            <p className="text-gray-600">
              This system uses fuzzy matching for intelligent search, predictive analytics for popular searches,
              and real-time notifications for outdated records. The department distribution chart automatically
              syncs with your student data.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
